def hybrid_search(query, user_groups, k=6):
    kw = bm25_search(query, filter_groups=user_groups, limit=30)
    vec = vector_search(embed(query), filter_groups=user_groups, limit=30)

    # reciprocal rank fusion: reward chunks ranked high by either method
    scores = {}
    for results in (kw, vec):
        for rank, chunk in enumerate(results):
            scores[chunk.id] = scores.get(chunk.id, 0) + 1 / (60 + rank)

    fused = sorted(scores, key=scores.get, reverse=True)[:30]
    candidates = [get_chunk(cid) for cid in fused]
    reranked = rerank(query, candidates)
    return reranked[:k]

