def check_asset_rights(asset_id: str, region: str, format: str) -> dict:
    """Check whether an image or text asset is licensed for a region
    (for example 'US', 'EU') and format ('print', 'ebook', 'web')."""
    lic = rights_db.lookup(asset_id)
    ok = region in lic.regions and format in lic.formats
    return {"asset_id": asset_id, "licensed": ok,
